import functools
import inspect
from typing import Any, Dict, ForwardRef
from fastapi.dependencies.utils import get_typed_signature

# Simulate module_a
class A:
    pass

def original(x: "A"):
    return x

# Simulate module_b
# We can't easily create modules in a script, but we can manipulate __globals__
# or just use a function that wraps another function from a different scope.

def create_wrapped():
    # This is like module_a
    class A:
        pass

    def original(x: "A"):
        return x

    # This is like module_b
    def wrapped_factory(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapper

    return wrapped_factory(original)

def test_repro():
    wrapped = create_wrapped()
    print(f"Wrapped function: {wrapped}")
    print(f"Wrapped annotations: {wrapped.__annotations__}")
    print(f"Wrapped globals: {wrapped.__globals__.get('A')}")

    # The original function is in __wrapped__
    original = wrapped.__wrapped__
    print(f"Original globals: {original.__globals__.get('A')}")

    try:
        sig = get_typed_signature(wrapped)
        print("Success: get_typed_signature worked")
    except NameError as e:
        print(f"Caught expected NameError: {e}")
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")
        import traceback
        traceback.print_exc()

if __name__ == "__main__":
    test_repro()
